export default function BrandCharacter({
  width = 200,
  style,
}: {
  width?: number;
  style?: StyleProp<ViewStyle>;
}) {
  const height = width * (2104 / 1982);

  const floatY   = useRef(new Animated.Value(0)).current;
  const tassleRot = useRef(new Animated.Value(-20)).current;
  const blinkSc  = useRef(new Animated.Value(1)).current;
  const armRot   = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    // Float — uses native driver (translateY only)
    Animated.loop(
      Animated.sequence([
        Animated.timing(floatY, { toValue: -6, duration: 2000, easing: Easing.inOut(Easing.ease), useNativeDriver: true }),
        Animated.timing(floatY, { toValue:  0, duration: 2000, easing: Easing.inOut(Easing.ease), useNativeDriver: true }),
      ])
    ).start();

    // Tassel swing — SVG prop, must use JS driver
    Animated.loop(
      Animated.sequence([
        Animated.timing(tassleRot, { toValue:  20, duration: 1950, easing: Easing.inOut(Easing.ease), useNativeDriver: false }),
        Animated.timing(tassleRot, { toValue: -20, duration: 1950, easing: Easing.inOut(Easing.ease), useNativeDriver: false }),
      ])
    ).start();

    // Eye blink
    Animated.loop(
      Animated.sequence([
        Animated.delay(4988),
        Animated.timing(blinkSc, { toValue: 0.05, duration: 290, useNativeDriver: false }),
        Animated.timing(blinkSc, { toValue: 1,    duration: 522, useNativeDriver: false }),
      ])
    ).start();

    // Arm wave
    Animated.loop(
      Animated.sequence([
        Animated.timing(armRot, { toValue: -25, duration:  850, easing: Easing.inOut(Easing.ease), useNativeDriver: false }),
        Animated.timing(armRot, { toValue:  12, duration: 1700, easing: Easing.inOut(Easing.ease), useNativeDriver: false }),
        Animated.timing(armRot, { toValue:   0, duration:  850, easing: Easing.inOut(Easing.ease), useNativeDriver: false }),
      ])
    ).start();
  }, []);

  return (
    <Animated.View style={[{ transform: [{ translateY: floatY }] }, style]}>
      <Svg width={width} height={height} viewBox="0 0 1982 2104">
        <Path d={P_CAP_TOP} fill="#001645" transform="translate(956.875,-0.3125)" />
        <Path d={P_COLLAR} fill="#66338F" transform="translate(453.6484375,1052.8125)" />
        <Path d={P_BODY} fill="#03297B" transform="translate(952,0)" />
        <Path d={P_ARM_L} fill="#022261" transform="translate(353,1175)" />

        {/* Arm wave */}
        <AnimatedG rotation={armRot as any} originX={1562} originY={1194}>
          <Path d={P_ARM_R} fill="#022261" transform="translate(1552,1174)" />
        </AnimatedG>

        {/* Tassel swing */}
        <AnimatedG rotation={tassleRot as any} originX={1806} originY={546}>
          <Path d={P_TASSEL} fill="#EBA604" transform="translate(1776,545)" />
        </AnimatedG>

        <Path d={P_FACE} fill="#F9F9FB" transform="translate(947.8125,380.8125)" />
        <Path d={P_SHOE_L} fill="#F7B106" transform="translate(719,1863)" />
        <Path d={P_SHOE_R} fill="#F7B106" transform="translate(1103,1862)" />
        <Path d={P_LEG_L} fill="#022260" transform="translate(719,1632)" />
        <Path d={P_LEG_R} fill="#022260" transform="translate(1190,1630)" />
        <Path d={P_GLOVE_L} fill="#FBFBFC" transform="translate(289.75,1507.8125)" />
        <Path d={P_GLOVE_R} fill="#FBFBFC" transform="translate(1688.15234375,1523.69140625)" />
        <Path d={P_SMILE} fill="#012160" transform="translate(809.09375,1271.72265625)" />

        {/* Eye blink — each eye gets its own AnimatedG */}
        <AnimatedG scaleY={blinkSc as any} originX={1258} originY={1058}>
          <Path d={P_EYE_R} fill="#012160" transform="translate(1208.1875,1008.25390625)" />
        </AnimatedG>
        <AnimatedG scaleY={blinkSc as any} originX={841} originY={1057}>
          <Path d={P_EYE_L} fill="#012160" transform="translate(791.296875,1006.71875)" />
        </AnimatedG>
      </Svg>
    </Animated.View>
  );
}
